const LABELS = {
  shot: { F: 'Forehand', B: 'Backhand' },
  area: { TL: 'Top Left', TR: 'Top Right', BL: 'Bottom Left', BR: 'Bottom Right', FH: 'Five Hole' },
  save: { G: 'Glove', B: 'Blocker', P: 'Pad', S: 'Stick', M: 'Miss' },
};

// Market IDs and selection codes per the Game Overview (2025/11/18).
const MARKETS = {
  MR:  { name: 'Match Result' },
  SST: { name: 'Score + Shot Type' },
  SSL: { name: 'Score + Target Area' },
  GST: { name: 'Save + Save Type' },
  STL: { name: 'Score + Shot Type + Target Area' },
};

const AREAS = ['TL', 'TR', 'BL', 'BR', 'FH'];
const SHOTS = ['F', 'B'];
const SAVES = ['G', 'B', 'P', 'S', 'M'];

const SELECTIONS = {
  MR: ['G', 'NG'],
  SST: SHOTS,
  SSL: AREAS,
  GST: SAVES,
  STL: SHOTS.flatMap(s => AREAS.map(a => s + a)),
};

function artSrc(p, hi = false) {
  return `${ART_PATH}${p.art}/${p.file}${hi ? '@2x' : ''}.webp`;
}
